/// <summary>
/// Service class for VFD variance vendor Claim process. 
/// </summary>
class METVFDVarVendClaimJournalService  extends SysOperationServiceBase implements BatchRetryable
{
    LedgerJournalName                 ledgerJournalName;
    METVFDVarVendClaimJournalContract contract;
    METExciseDutyParameteres          exciseDutyParameters;
    MetVendClaimType                  claimType;
    InvoiceDate                       invoiceDate;
    InventLocationId                  warehouse;
    Description255                    itemDescription;
    ItemId                            itemId;
    VendAccount                       vendorAccount;
    LanguageId                        languageId;

    RecordInsertList              ledgerJournalTransRecordList;

}

Method.Source:
/// <summary>
/// Entry point operation method for processing claims
/// </summary>
/// <param name = "_contract">Data contract</param>
public void processOperation(METVFDVarVendClaimJournalContract _contract)
{
    contract = _contract;
    exciseDutyParameters = METExciseDutyParameteres::find();
    this.processClaims();
}

/// <summary>
/// Initialise class variables
/// </summary>
private void initParameters()
{
    invoiceDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    ledgerJournalName = LedgerJournalName::find(exciseDutyParameters.ExciseClaimJournalName);

    languageId = CompanyInfo::languageId();

    ledgerJournalTransRecordList = new RecordInsertList(tableNum(LedgerJournalTrans));
}

/// <summary>
/// Process claim
/// </summary>
private void processClaims()
{
    #OCCRetryCount

    METVendorClaimTable vendorClaimTable;
    boolean first = true, createJournalHeader = false;
    VendAccount prevVendAccount;
    LedgerJournalTable ledgerJournalTable;
    VendTable vendTable;

    RecordSortedList journalHeaderList = new RecordSortedList(tableNum(LedgerJournalTable));
    journalHeaderList.sortOrder(fieldNum(LedgerJournalTable, JournalNum));

    this.initParameters();

    if (!ledgerJournalName)
    {
        throw error("@MET:VFDVarVendClaimJourNameError");
    }

    if (!exciseDutyParameters.ExciseClaimNumberSequence)
    {
        throw error("@MET:VFDVarVendClaimJourNumberSeqError");
    }

    if (!exciseDutyParameters.AccrualAccountNum)
    {
        throw error("@MET:VFDVarVendClaimJourOffsetAccountError");
    }

    QueryRun qr = new QueryRun(contract.getQuery());

    while (qr.next())
    {
        vendorClaimTable = qr.get(tableNum(METVendorClaimTable));
        try
        {
            ttsbegin;
            if (first)
            {
                createJournalHeader = true;
                first = false;
                vendTable = VendTable::find(vendorClaimTable.VendAccount);
            }
            else if (prevVendAccount != vendorClaimTable.VendAccount)
            {
                createJournalHeader = true;
                vendTable = VendTable::find(vendorClaimTable.VendAccount);
            }

            // Create one journal header per vendor account
            if (createJournalHeader)
            {
                ledgerJournalTable = this.createLedgerJournalTable();
                createJournalHeader = false;
                journalHeaderList.ins(ledgerJournalTable);
            }

            this.createJournalLines(vendorClaimTable, ledgerJournalTable, vendTable);

            prevVendAccount = vendorClaimTable.VendAccount;
            ttscommit;

        }
        catch (Exception::Error)
        {
            error ("@MET:VFDVarVendorClaimProcessCanceled");

        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                error("@Subledger:DeadlockErrorThrown");
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@Subledger:UpdateConflictErrorThrown");
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@Subledger:UpdateConflictErrorThrown");
            }
        }
    }

    // bulk insert journal lines before journal posting to improve performance
    ledgerJournalTransRecordList.insertDatabase();

    //Split transaction blocks to separate journal creation and posting. In case posting fails, journal will remain in system and manual posting can be done
    this.postJournalHeaders(journalHeaderList);

}

/// <summary>
/// Create journal header for each vendor
/// </summary>
/// <returns><c>LedgerJournalTable</c> journal header record</returns>
private LedgerJournalTable createLedgerJournalTable()
{
    LedgerJournalTable ledgerJournalTable;

    ledgerJournalTable.initFromLedgerJournalName(ledgerJournalName.JournalName);
    ledgerJournalTable.insert();

    return ledgerJournalTable;
}

/// <summary>
/// Create journal lines for vendor claims
/// </summary>
/// <param name = "_vendorClaimTable"><c>METVendorClaimTable</c> record</param>
/// <param name = "_journalTable"><c>LedgerJournalTable</c> journal header record</param>
/// <param name = "_vendTable"><c>VendTable</c> record</param>
private void createJournalLines(METVendorClaimTable _vendorClaimTable, LedgerJournalTable _journalTable, VendTable _vendTable)
{
    LedgerJournalTrans                  ledgerJournalTrans, ledgerJournalTransArrued;
    LedgerJournalTable                  ledgerJournalTableAccrued;                                    
    InventSiteLinkedDimensionValueSet   defaultDimension;
    InventLocation                      inventLocation;
    METDutyRollVariance                 dutyRollVariance;
    MainAccount                         mainAccount;
    Voucher                             voucher;
    InvoiceId                           invoiceId;
    AmountCur                           claimAmount;

    // get the voucher and invoice number for the set of vendor/ledger lines
    voucher = this.getClaimJournalVoucherNumberSeq().voucher();
    invoiceId = this.getClaimInvoiceNumberSeq().num();
    claimAmount = _vendorClaimTable.ClaimAmount;

    ledgerJournalTrans.clear();
    ledgerJournalTrans.initValue();
    ledgerJournalTrans.JournalNum    = _journalTable.JournalNum;
    ledgerJournalTrans.Voucher       = voucher;
    ledgerJournalTrans.Invoice       = invoiceId;

    ledgerJournalTrans.DocumentDate  = invoiceDate;
    ledgerJournalTrans.TransDate     = invoiceDate;
    ledgerJournalTrans.CurrencyCode  = _journalTable.CurrencyCode;

    ledgerJournalTrans.AccountType     = LedgerJournalACType::Vend;

    ledgerJournalTrans.parmAccount(_vendTable.AccountNum);

    ledgerJournalTrans.AmountCurDebit = claimAmount;

    ledgerJournalTrans.LedgerDimension = LedgerDynamicAccountHelper::getDynamicAccountFromAccountNumber(_vendTable.AccountNum, LedgerJournalACType::Vend);
    ledgerJournalTrans.modifiedField(fieldNum(LedgerJournalTrans, LedgerDimension));

    select firstonly ExciseRegisterReferenceId from dutyRollVariance
        where dutyRollVariance.RecId == _vendorClaimTable.DutyRollVariance;

    //Offset account
    mainAccount = MainAccount::findByMainAccountId(exciseDutyParameters.AccrualAccountNum);
    ledgerJournalTrans.OffsetAccountType  = LedgerJournalACType::Ledger;

    if (dutyRollVariance.ExciseRegisterReferenceId)
    {
        select firstonly ledgerJournalTransArrued
            order by CreatedDateTime desc
                exists join ledgerJournalTableAccrued
                    where ledgerJournalTableAccrued.JournalNum == ledgerJournalTransArrued.JournalNum
                    &&    ledgerJournalTableAccrued.Posted == NoYes::Yes
                    &&    ledgerJournalTableAccrued.METExciseRegisterReferenceId == dutyRollVariance.ExciseRegisterReferenceId;

        defaultDimension = LedgerDimensionFacade::getDefaultDimensionFromLedgerDimension(ledgerJournalTransArrued.OffsetLedgerDimension);
    }
    else
    {
        defaultDimension = _vendTable.DefaultDimension;
    }

    ledgerJournalTrans.DefaultDimension       = defaultDimension;
    ledgerJournalTrans.OffsetLedgerDimension  = METDutyRollVarianceAccuralJournalPostingHelper::combineMainAccoutAndDefaultDimension(mainAccount.MainAccountId, defaultDimension);
    ledgerJournalTrans.Txt                    = strFmt("@MET:DutyVarianceVendorDesc", _vendorClaimTable.VendAccount);
    ledgerJournalTrans.TaxGroup               = _vendTable.TaxGroup;
    ledgerJournalTrans.TaxItemGroup           = exciseDutyParameters.TaxItemGroup;

    ledgerJournalTrans.markAsApprovedByCurrentUser();

    ledgerJournalTransRecordList.add(ledgerJournalTrans);

    this.updateClaimDetails(ledgerJournalTrans.Invoice, ledgerJournalTrans.DocumentDate, _vendorClaimTable, _journalTable.JournalNum);
}

/// <summary>
/// Gets the claim voucher number sequence
/// </summary>
/// <returns>Voucher numebr sequence</returns>
private NumberSeq getClaimJournalVoucherNumberSeq()
{
    return NumberSeq::newGetVoucherFromCode(NumberSequenceTable::find(ledgerJournalName.NumberSequenceTable).NumberSequence,
                                            NumberSeqScopeFactory::createDefaultScope(),
                                            false);
}

/// <summary>
/// Gets the claim invoice number sequence
/// </summary>
/// <returns>invoice numebr sequence</returns>
private NumberSeq getClaimInvoiceNumberSeq()
{
    return NumberSeq::newGetNumFromId(exciseDutyParameters.ExciseClaimNumberSequence);
}

/// <summary>
/// Post journals created or not
/// </summary>
/// <param name = "_journalHeaderList">Created journals from previous process</param>
private void postJournalHeaders(RecordSortedList _journalHeaderList)
{
    #OCCRetryCount

    boolean moreRecs;
    LedgerJournalTable ledgerJournalTable;

    moreRecs = _journalHeaderList.first(ledgerJournalTable);

    while (moreRecs)
    {
        // if one journal posting errors, go to the next journal posting
        try
        {
            ttsbegin;
            if (true)
            {
                this.postClaimJournal(ledgerJournalTable);
                info(strFmt("@MET:VFDVarVendorClaimJournalPosted", ledgerJournalTable.JournalNum));
            }
            else
            {
                info(strFmt("@MET:VFDVarVendorClaimJournalCreated", ledgerJournalTable.JournalNum));
            }
            moreRecs = _journalHeaderList.next(ledgerJournalTable);
            ttscommit;
        }
        catch (Exception::Error)
        {
            error(strFmt("@MET:ErrorPostingJournal", ledgerJournalTable.JournalNum));
            moreRecs = _journalHeaderList.next(ledgerJournalTable);
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                error("@Subledger:DeadlockErrorThrown");
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@Subledger:UpdateConflictErrorThrown");
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@Subledger:UpdateConflictErrorThrown");
            }
        }
    }
}

/// <summary>
/// Posts the claim journal
/// </summary>
/// <param name = "_ledgerJournalTable"><c>LedgerJournalTable</c> journal header record</param>
private void postClaimJournal(LedgerJournalTable _ledgerJournalTable)
{
    METVendorClaimTable vendClaimTableUpd;

    if (_ledgerJournalTable)
    {
        LedgerJournalPost::postJournal(_ledgerJournalTable, NoYes::Yes);
    }
}

/// <summary>
/// Update claim details in the vendor claim register against respective claim lines
/// </summary>
/// <param name = "_invoiceId">Invoice number</param>
/// <param name = "_invoiceDate">Invoice date</param>
/// <param name = "_vendorClaimTable"><c>METVendorClaimTable</c> record</param>
/// <param name = "_journalNum"><c>LedgerJournalTable</c> journal number</param>
private void updateClaimDetails(VendInvoiceId _invoiceId, InvoiceDate _invoiceDate, METVendorClaimTable _vendorClaimTable, LedgerJournalId _journalNum)
{
    METVendorClaimTable vendorClaimTableUpd;

    update_recordset vendorClaimTableUpd
        Setting ClaimInvoiceId  = _invoiceId,
                ClaimDate       = _invoiceDate,
                JournalId       = _journalNum,
                LedgerDimension = ledgerJournalName.OffsetLedgerDimension
        where   vendorClaimTableUpd.RecId == _vendorClaimTable.RecId;
}

/// <summary>
/// Updates Claimed status field.
/// </summary>
/// <param name="_ledgerJournalCheckPost"></param>
/// <param name="_postingSuccess"></param>
/// <param name="_intercompanyPostingSuccess"></param>
[SubscribesTo(classStr(LedgerJournalCheckPost), delegateStr(LedgerJournalCheckPost, runInternalPostPostJournalDelegate))]
public static void LedgerJournalCheckPost_runInternalPostPostJournalDelegate(LedgerJournalCheckPost _ledgerJournalCheckPost, boolean _postingSuccess, boolean _intercompanyPostingSuccess)
{
    if (_postingSuccess)
    {
        LedgerJournalName ledgerJournalName;

        ledgerJournalName = _ledgerJournalCheckPost.ledgerJournalName;

        if (METExciseDutyParameteres::find().ExciseClaimJournalName == ledgerJournalName.JournalName)
        {
            MetVendorClaimTable vendClaimTableUpd;
            LedgerJournalTable ledgerJournalTable;

            ledgerJournalTable = _ledgerJournalCheckPost.ledgerJournalTable;

            update_recordset vendClaimTableUpd
                setting Claimed = NoYes::Yes,
                        ClaimStatus = METVendorClaimStatus::Approved
                where vendClaimTableUpd.JournalId == ledgerJournalTable.JournalNum;
        }
    }

}

/// <summary>
/// Control whether batch task should retry in case of SQL transient errors.
/// </summary>
/// <returns>true if task should be retried; otherwise, false.</returns>
public boolean isRetryable()
{
    return true;
}
